SELECT

FROM deployment_runs

    workspace_uuid = #{params.WorkspaceUUID}
    AND deleted_at IS NULL

        AND deployment_external_id = #{params.DeploymentExternalID}


        AND trigger_type = #{params.TriggerType}




                AND error IS NOT NULL


                AND error IS NULL




        AND created_at > #{params.CreatedAtGT}


        AND created_at >= #{params.CreatedAtGTE}


        AND created_at < #{params.CreatedAtLT}


        AND created_at <= #{params.CreatedAtLTE}


        AND (created_at, uuid) < (#{params.Cursor.CreatedAt}, #{params.Cursor.UUID})


ORDER BY created_at DESC, uuid DESC
LIMIT #{params.FetchLimit}
